SELECT id, category_id, name, model, status, description, created_at, updated_at
FROM devices


        AND name LIKE CONCAT('%', #{name}, '%')


        AND model LIKE CONCAT('%', #{model}, '%')


        AND status = #{status}


        AND category_id = #{categoryId}


ORDER BY created_at DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM devices


        AND name LIKE CONCAT('%', #{name}, '%')


        AND model LIKE CONCAT('%', #{model}, '%')


        AND status = #{status}


        AND category_id = #{categoryId}

SELECT id, category_id, name, model, status, description, created_at, updated_at FROM devices
AND status = 'NORMAL'
AND name LIKE CONCAT('%', #{name}, '%')
AND category_id = #{categoryId}
ORDER BY created_at DESC LIMIT #{offset}, #{size}
